/*
 * Smoke tests for the playlist rewriting logic — page path and worker path.
 * Run with: node dev/test-rewrite.mjs
 *
 * The content script is a browser IIFE, so we execute it inside a tiny fake
 * window with just enough DOM/MediaSource/Blob surface to install the hooks.
 * The worker shim is generated by the same code path used at runtime and then
 * executed inside a fake WorkerGlobalScope.
 */
import fs from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';

const source = fs.readFileSync(new URL('../src/main-world.js', import.meta.url), 'utf8');

/* ------------------------------------------------------------------ *
 * Fixtures — mirror of a real F1TV (AWS MediaPackage) master playlist
 * captured from the Pro tier: 5 AVC + 5 HEVC renditions, 270p → 1080p50.
 * ------------------------------------------------------------------ */

const Q = '?end=2026-10-24T05%3A10%3A45-00%3A00&start=2026-10-23T17%3A10%3A45-00%3A00';

const AUDIO_LINES = [
  `#EXT-X-MEDIA:LANGUAGE="eng",AUTOSELECT=YES,CHANNELS="2",TYPE=AUDIO,URI="index__AUDIO_2.m3u8${Q}",GROUP-ID="audio_0",DEFAULT=NO,NAME="eng"`,
  `#EXT-X-MEDIA:LANGUAGE="spa",AUTOSELECT=YES,CHANNELS="2",TYPE=AUDIO,URI="index__AUDIO_4.m3u8${Q}",GROUP-ID="audio_0",DEFAULT=NO,NAME="spa"`,
  `#EXT-X-MEDIA:LANGUAGE="eng",AUTOSELECT=YES,FORCED=NO,TYPE=SUBTITLES,URI="index__SUBS_1.m3u8${Q}",GROUP-ID="subtitles",DEFAULT=NO,NAME="eng_subtitle"`
];

const RENDITIONS = [
  { name: 'AVC_1', codecs: 'mp4a.40.2,avc1.4D401E', avg: 774400, bw: 796928, res: '480x270' },
  { name: 'AVC_2', codecs: 'mp4a.40.2,avc1.4D401F', avg: 1213696, bw: 1253795, res: '640x360' },
  { name: 'AVC_3', codecs: 'mp4a.40.2,avc1.4D401F', avg: 2464000, bw: 2554112, res: '960x540' },
  { name: 'AVC_4', codecs: 'mp4a.40.2,avc1.4D4020', avg: 4221184, bw: 4381582, res: '1280x720' },
  { name: 'AVC_5', codecs: 'mp4a.40.2,avc1.4D402A', avg: 6969600, bw: 7239936, res: '1920x1080' },
  { name: 'HEVC_1', codecs: 'mp4a.40.2,hev1.1.6.L93.B0', avg: 661760, bw: 679782, res: '480x270' },
  { name: 'HEVC_2', codecs: 'mp4a.40.2,hev1.1.6.L93.B0', avg: 1013196, bw: 1045276, res: '640x360' },
  { name: 'HEVC_3', codecs: 'mp4a.40.2,hev1.1.6.L93.B0', avg: 2013440, bw: 2085529, res: '960x540' },
  { name: 'HEVC_4', codecs: 'mp4a.40.2,hev1.1.6.L123.B0', avg: 3419187, bw: 3547506, res: '1280x720' },
  { name: 'HEVC_5', codecs: 'mp4a.40.2,hev1.1.6.L123.B0', avg: 6406400, bw: 6654208, res: '1920x1080' }
];

function variantLine(r, extra = '') {
  return (
    `#EXT-X-STREAM-INF:CODECS="${r.codecs}",AVERAGE-BANDWIDTH=${r.avg},RESOLUTION=${r.res},` +
    `VIDEO-RANGE=${r.range || 'SDR'},SUBTITLES="subtitles",FRAME-RATE=50.0,BANDWIDTH=${r.bw}` +
    `${extra},AUDIO="audio_0"\nindex__SDR-HD_${r.name}.m3u8${Q}`
  );
}

function makeMaster({ hdr = false } = {}) {
  const lines = [
    '#EXTM3U',
    '#EXT-X-VERSION:7',
    '#EXT-X-INDEPENDENT-SEGMENTS',
    '#EXT-X-SESSION-KEY:KEYFORMATVERSIONS="1",METHOD=SAMPLE-AES,KEYID=0x71E9286C546D3387B878CEDD4BA64C6A,URI="data:text/plain;base64,AAAAV3Bzc2gAAAAA",KEYFORMAT="urn:uuid:edef8ba9-79d6-4ace-a3c8-27dcd51d21ed"',
    ...AUDIO_LINES,
    ...RENDITIONS.map((r) => variantLine(r))
  ];
  if (hdr) {
    lines.push(
      variantLine({
        name: 'HDR_HEVC_6',
        codecs: 'mp4a.40.2,hvc1.2.4.L153.B0',
        avg: 18000000,
        bw: 19000000,
        res: '3840x2160',
        range: 'PQ'
      })
    );
  }
  lines.push(
    `#EXT-X-I-FRAME-STREAM-INF:CODECS="avc1.4D402A",RESOLUTION=1920x1080,VIDEO-RANGE=SDR,BANDWIDTH=3072000,URI="index__SDR-HD_AVC_5_iframe.m3u8${Q}"`
  );
  return lines.join('\r\n') + '\r\n';
}

const MASTER = makeMaster();
const HDR_MASTER = makeMaster({ hdr: true });

const MEDIA = [
  '#EXTM3U',
  '#EXT-X-VERSION:7',
  '#EXT-X-PLAYLIST-TYPE:EVENT',
  '#EXT-X-TARGETDURATION:6',
  '#EXT-X-MAP:URI="segment__SDR-HD_AVC_5_311244403_init.mp4"',
  '#EXTINF:5.76,',
  'segment__SDR-HD_AVC_5_311245737.mp4',
  ''
].join('\n');

/* ------------------------------------------------------------------ *
 * Page sandbox
 * ------------------------------------------------------------------ */

function makeWindow({ supportedCodecs = null } = {}) {
  class FakeXHR {
    constructor() {
      this.readyState = 0;
      this.responseType = '';
      this._text = '';
    }
    get responseText() {
      return this._text;
    }
    get response() {
      return this._text;
    }
    open() {}
    send() {}
    getResponseHeader() {
      return null;
    }
  }

  const created = [];
  const posted = [];
  const U = URL;
  function FakeURL(input, base) {
    return new U(input, base);
  }
  FakeURL.createObjectURL = (blob) => {
    created.push(blob);
    return 'blob:test-' + created.length;
  };
  FakeURL.revokeObjectURL = () => {};

  const sandbox = {
    console,
    Blob,
    Headers,
    Response,
    TextEncoder,
    TextDecoder,
    URL: FakeURL,
    setTimeout: (fn) => setTimeout(fn, 0).unref?.(),
    clearTimeout,
    location: { href: 'https://f1tv.formula1.com/' },
    document: {
      documentElement: null,
      querySelectorAll: () => [],
      createElement: () => ({ canPlayType: () => '' })
    },
    MutationObserver: class {
      observe() {}
    },
    MediaSource: {
      isTypeSupported: (type) => {
        if (!supportedCodecs) return true;
        return supportedCodecs.some((codec) => type.includes(codec));
      }
    },
    XMLHttpRequest: FakeXHR,
    BroadcastChannel: class {
      constructor() {}
      postMessage() {}
      close() {}
    },
    postMessage: (msg) => posted.push(msg),
    addEventListener: () => {},
    __created: created,
    __posted: posted
  };
  sandbox.window = sandbox;
  return sandbox;
}

function load(options) {
  const sandbox = makeWindow(options);
  const bodies = new Map();
  sandbox.fetch = async (input) => {
    const url = typeof input === 'string' ? input : input.url;
    const body = bodies.has(url) ? bodies.get(url) : MASTER;
    return new Response(body, {
      status: 200,
      headers: { 'content-type': 'application/vnd.apple.mpegurl' }
    });
  };
  sandbox.__bodies = bodies;
  vm.runInNewContext(source, sandbox, { filename: 'main-world.js' });
  return sandbox;
}

const run = (sandbox, text) => sandbox.__f1hqInternals.buildMaster(text);
const countVariants = (text) => (text.match(/#EXT-X-STREAM-INF:/g) || []).length;

/* ------------------------------------------------------------------ *
 * Worker sandbox (for the generated shim)
 * ------------------------------------------------------------------ */

function makeWorkerSandbox(respond) {
  function WorkerGlobalScope() {}

  const sandbox = Object.create(WorkerGlobalScope.prototype);
  sandbox.WorkerGlobalScope = WorkerGlobalScope;
  sandbox.self = sandbox;
  sandbox.console = console;
  sandbox.Blob = Blob;
  sandbox.Headers = Headers;
  sandbox.Response = Response;
  sandbox.TextEncoder = TextEncoder;
  sandbox.TextDecoder = TextDecoder;
  sandbox.URL = URL;
  sandbox.setTimeout = (fn) => setTimeout(fn, 0).unref?.();
  sandbox.clearTimeout = clearTimeout;

  const channels = [];
  sandbox.__channels = channels;
  sandbox.BroadcastChannel = class {
    constructor(name) {
      this.name = name;
      this.onmessage = null;
      this.sent = [];
      channels.push(this);
    }
    postMessage(msg) {
      this.sent.push(msg);
    }
    close() {}
  };

  sandbox.__requests = [];
  sandbox.fetch = async (input) => {
    const url = typeof input === 'string' ? input : input.url;
    sandbox.__requests.push(url);
    return new Response(respond(url), {
      status: 200,
      headers: { 'content-type': 'application/vnd.apple.mpegurl' }
    });
  };

  return sandbox;
}

function loadWorker(sandbox, shimSource) {
  vm.runInNewContext(shimSource, sandbox, { filename: 'worker-shim.js' });
  return sandbox;
}

/* ================================================================== *
 * Tests
 * ================================================================== */

/* 1. Default: highest bandwidth wins, everything else is preserved. */
{
  const win = load();
  const parsed = run(win, MASTER);
  assert.ok(parsed, 'master playlist should parse');
  assert.equal(parsed.variants.length, 10);
  assert.equal(parsed.chosen.bandwidth, 7239936, 'should pick 1080p AVC (highest BANDWIDTH)');
  assert.equal(countVariants(parsed.text), 1, 'rewritten master must expose one variant');
  assert.match(parsed.text, /index__SDR-HD_AVC_5\.m3u8/);
  assert.doesNotMatch(parsed.text, /index__SDR-HD_AVC_4\.m3u8/);
  assert.doesNotMatch(parsed.text, /HEVC_5/);
  assert.equal((parsed.text.match(/#EXT-X-MEDIA:/g) || []).length, 3, 'audio + subtitle renditions must survive');
  assert.match(parsed.text, /#EXT-X-SESSION-KEY/);
  assert.match(parsed.text, /#EXT-X-I-FRAME-STREAM-INF/);
  assert.match(parsed.text, /\r\n/, 'CRLF line endings are preserved');
  assert.match(parsed.text, /index__AUDIO_2\.m3u8\?end=/, 'query params on media URIs survive');
  console.log('ok 1 — picks 1080p AVC, keeps audio/subs/iframe/DRM tags');
}

/* 2. Cap mode. */
{
  const win = load();
  const cfg = win.__f1hqInternals.getConfig();
  cfg.strategy = 'cap';
  cfg.capMbps = 5;
  const parsed = run(win, MASTER);
  assert.equal(parsed.chosen.bandwidth, 4381582, 'cap 5 Mbps -> 720p AVC');
  assert.match(parsed.text, /index__SDR-HD_AVC_4\.m3u8/);
  console.log('ok 2 — bitrate cap picks the highest variant under the cap');
}

/* 3. Avoid HDR. */
{
  const win = load();
  win.__f1hqInternals.getConfig().avoidHdr = true;
  const parsed = run(win, HDR_MASTER);
  assert.equal(parsed.chosen.bandwidth, 7239936, '19 Mbps HDR variant must be skipped');
  assert.doesNotMatch(parsed.text, /HDR_HEVC_6/);
  console.log('ok 3 — avoid HDR skips PQ/HLG variants');
}

/* 4. Codec support filtering. */
{
  const win = load({ supportedCodecs: ['avc1'] });
  const parsed = run(win, HDR_MASTER);
  assert.equal(parsed.chosen.bandwidth, 7239936, 'unsupported HEVC/HDR must be skipped even without avoidHdr');
  console.log('ok 4 — unsupported codecs are skipped');
}

/* 5. Media playlists are left alone. */
{
  const win = load();
  assert.equal(run(win, MEDIA), null, 'media playlists must not be rewritten');
  assert.equal(run(win, '<html>nope</html>'), null);
  console.log('ok 5 — media playlists / non-m3u8 bodies untouched');
}

/* 6. Single-variant masters are reported but never rewritten. */
{
  const win = load();
  const single = [
    '#EXTM3U',
    '#EXT-X-STREAM-INF:BANDWIDTH=5500000,RESOLUTION=1920x1080',
    '1080/index.m3u8',
    ''
  ].join('\n');
  const parsed = run(win, single);
  assert.ok(parsed);
  assert.equal(parsed.chosen.bandwidth, 5500000);
  assert.equal(parsed.text, null, 'single-variant master needs no rewrite');
  console.log('ok 6 — single-variant master is reported without rewriting');
}

/* 7. Page fetch hook end-to-end. */
{
  const win = load();
  const response = await win.fetch('https://example.test/index.m3u8?token=secret');
  const text = await response.text();
  assert.equal(countVariants(text), 1);
  assert.match(text, /index__SDR-HD_AVC_5\.m3u8/);
  assert.equal(response.url, 'https://example.test/index.m3u8?token=secret', 'response.url preserved');
  console.log('ok 7 — page fetch hook rewrites the master and preserves response.url');
}

/* 8. Disabled config passes the playlist through untouched — but still reports. */
{
  const win = load();
  win.__f1hqInternals.getConfig().enabled = false;
  const response = await win.fetch('https://example.test/index.m3u8');
  assert.equal(countVariants(await response.text()), 10);

  const report = win.__posted.filter((m) => m.type === 'master').pop();
  assert.ok(report, 'master must still be reported while disabled');
  assert.equal(report.payload.enabled, false);
  assert.equal(report.payload.rewritten, false);
  console.log('ok 8 — disabled extension leaves the stream alone but still reports the ladder');
}

/* 9. XHR hook, including reuse of the same XHR object. */
{
  const win = load();
  const xhr = new win.XMLHttpRequest();
  xhr.open('GET', 'https://example.test/index.m3u8?token=abc');
  xhr._text = MASTER;
  xhr.readyState = 4;
  const rewritten = xhr.responseText;
  assert.equal(countVariants(rewritten), 1);
  assert.match(rewritten, /index__SDR-HD_AVC_5\.m3u8/);
  assert.equal(xhr.getResponseHeader('content-length'), String(Buffer.byteLength(rewritten)));

  xhr.open('GET', 'https://example.test/index__SDR-HD_AVC_5.m3u8?token=abc');
  xhr._text = MEDIA;
  xhr.readyState = 4;
  assert.equal(xhr.responseText, MEDIA);
  console.log('ok 9 — XHR hook rewrites masters and resets state on open()');
}

/* 10. createObjectURL: JS blobs get the shim prepended, others untouched. */
{
  const win = load();
  const workerSource = new Blob(['self.playerCode = true;'], { type: 'text/javascript;charset=utf-8' });
  const url = win.URL.createObjectURL(workerSource);
  assert.equal(url, 'blob:test-1');
  const wrapped = win.__created[0];
  assert.notEqual(wrapped, workerSource, 'a new blob should be created');
  const text = await wrapped.text();
  assert.match(text, /__f1hqWorker/, 'shim should be prepended');
  assert.match(text, /self\.playerCode = true;/, 'original source must be intact');
  assert.ok(text.indexOf('__f1hqWorker') < text.indexOf('self.playerCode'), 'shim must run first');

  const css = new Blob(['body{}'], { type: 'text/css' });
  win.URL.createObjectURL(css);
  assert.equal(win.__created[1], css, 'non-JS blobs must not be wrapped');
  console.log('ok 10 — createObjectURL injects the shim into JavaScript blobs only');
}

/* 11. Worker shim end-to-end: rewrites inside the worker + reports. */
{
  const win = load();
  const shim = win.__f1hqInternals.buildWorkerSource();
  const worker = makeWorkerSandbox(() => MASTER);
  loadWorker(worker, shim);

  assert.equal(worker.__f1hqWorker, true, 'shim should mark the worker');

  const response = await worker.self.fetch('https://cdn.test/index.m3u8?token=t');
  const text = await response.text();
  assert.equal(countVariants(text), 1);
  assert.match(text, /index__SDR-HD_AVC_5\.m3u8/);
  assert.equal(response.url, 'https://cdn.test/index.m3u8?token=t', 'worker response.url preserved');

  const report = worker.__channels[0].sent.find((m) => m.type === 'master');
  assert.ok(report, 'worker should report the master over BroadcastChannel');
  assert.equal(report.payload.source, 'worker');
  assert.equal(report.payload.rewritten, true);
  assert.equal(report.payload.variants.length, 10);
  assert.equal(report.payload.chosen.bandwidth, 7239936);
  assert.doesNotMatch(report.payload.url, /token=/, 'reported URL must not leak the token');
  console.log('ok 11 — worker shim rewrites the master inside the worker and reports it');
}

/* 12. Worker shim honours live config updates over BroadcastChannel. */
{
  const win = load();
  const shim = win.__f1hqInternals.buildWorkerSource();
  const worker = makeWorkerSandbox(() => MASTER);
  loadWorker(worker, shim);

  const channel = worker.__channels[0];
  channel.onmessage({
    data: { __f1hq: true, type: 'config', payload: { strategy: 'cap', capMbps: 5 } }
  });

  const response = await worker.self.fetch('https://cdn.test/index.m3u8?second=1');
  const text = await response.text();
  assert.equal(countVariants(text), 1);
  assert.match(text, /index__SDR-HD_AVC_4\.m3u8/, 'live cap update should switch to 720p');
  console.log('ok 12 — worker shim applies live config changes');
}

/* 13. Worker shim leaves media playlists alone and caches the decision. */
{
  const win = load();
  const shim = win.__f1hqInternals.buildWorkerSource();
  const worker = makeWorkerSandbox((url) => (url.includes('AVC_5') ? MEDIA : MASTER));
  loadWorker(worker, shim);

  const mediaUrl = 'https://cdn.test/index__SDR-HD_AVC_5.m3u8';
  const first = await worker.self.fetch(mediaUrl);
  assert.equal(await first.text(), MEDIA);

  const second = await worker.self.fetch(mediaUrl);
  assert.equal(await second.text(), MEDIA);
  assert.equal(worker.__requests.length, 2, 'body must still be fetched every time');
  console.log('ok 13 — worker shim ignores media playlists');
}

/* 14. The shim is a no-op outside a worker (e.g. blobs used for scripts). */
{
  const win = load();
  const shim = win.__f1hqInternals.buildWorkerSource();
  const notAWorker = {
    document: {},
    fetch: async () => new Response('x')
  };
  notAWorker.self = notAWorker;
  vm.runInNewContext(shim, notAWorker);
  assert.equal(notAWorker.__f1hqWorker, undefined);
  console.log('ok 14 — shim refuses to install outside a WorkerGlobalScope');
}

/* 15. Worker shim reports the ladder even when disabled. */
{
  const win = load();
  win.__f1hqInternals.getConfig().enabled = false;
  const shim = win.__f1hqInternals.buildWorkerSource();
  const worker = makeWorkerSandbox(() => MASTER);
  loadWorker(worker, shim);

  const response = await worker.self.fetch('https://cdn.test/index.m3u8?off=1');
  assert.equal(countVariants(await response.text()), 10, 'disabled shim must not rewrite');

  const report = worker.__channels[0].sent.find((m) => m.type === 'master');
  assert.ok(report, 'worker must still report the ladder while disabled');
  assert.equal(report.payload.enabled, false);
  assert.equal(report.payload.rewritten, false);
  console.log('ok 15 — disabled worker shim still reports the ladder');
}

/* 16. Explicit pin selects the requested rendition. */
{
  const win = load();
  const cfg = win.__f1hqInternals.getConfig();
  cfg.strategy = 'pin';
  cfg.pin = { bandwidth: 4381582, resolution: '1280x720', codec: 'avc' };
  const parsed = run(win, MASTER);
  assert.equal(parsed.chosen.bandwidth, 4381582);
  assert.match(parsed.text, /index__SDR-HD_AVC_4\.m3u8/);
  console.log('ok 16 — pin forces the exact rendition the user picked');
}

/* 17. Pin can force a specific codec at the same resolution. */
{
  const win = load();
  const cfg = win.__f1hqInternals.getConfig();
  cfg.strategy = 'pin';
  cfg.pin = { bandwidth: 6654208, resolution: '1920x1080', codec: 'hevc' };
  const parsed = run(win, MASTER);
  assert.equal(parsed.chosen.bandwidth, 6654208);
  assert.match(parsed.text, /index__SDR-HD_HEVC_5\.m3u8/);
  console.log('ok 17 — pin distinguishes AVC vs HEVC at the same resolution');
}

/* 18. Pin to a rendition that disappeared: closest bandwidth wins. */
{
  const win = load();
  const cfg = win.__f1hqInternals.getConfig();
  cfg.strategy = 'pin';
  cfg.pin = { bandwidth: 19000000, resolution: '3840x2160', codec: 'hevc' };
  const parsed = run(win, MASTER);
  assert.equal(parsed.chosen.bandwidth, 7239936, 'nearest bandwidth to an unavailable 4K pin');
  console.log('ok 18 — missing pinned rendition falls back to the closest bandwidth');
}

/* 19. Worker shim honours a pinned quality pushed over BroadcastChannel. */
{
  const win = load();
  const shim = win.__f1hqInternals.buildWorkerSource();
  const worker = makeWorkerSandbox(() => MASTER);
  loadWorker(worker, shim);

  worker.__channels[0].onmessage({
    data: {
      __f1hq: true,
      type: 'config',
      payload: {
        strategy: 'pin',
        pin: { bandwidth: 2554112, resolution: '960x540', codec: 'avc' }
      }
    }
  });

  const response = await worker.self.fetch('https://cdn.test/index.m3u8?pin=1');
  assert.match(await response.text(), /index__SDR-HD_AVC_3\.m3u8/);
  console.log('ok 19 — worker shim honours a pinned quality');
}

console.log('\nall tests passed');
